'use strict';
// bot_bridge 本地桩：koishi 插件在桥接下运行所需的最小 API 面。
//
// Context 用 Proxy 兜底：koishi 的 context 是链式的（ctx.guild().command(...)、
// ctx.database 等），任何未知属性都返回一个新的同型代理；真实方法（command /
// on / middleware / logger / i18n / schema / emit / getCommand …）优先。
// 依赖 koishi 内部服务（database/console/model）的插件在**运行时访问**时会拿到
// 清晰错误（见 UNSUPPORTED），而不是静默假成功。

const { Schema } = require('schemastery');

class Logger {
  constructor(prefix, emit) {
    this._prefix = prefix || '';
    this._emit = emit;
  }
  info(...a) { this._emit('info', this._prefix, a); }
  warn(...a) { this._emit('warning', this._prefix, a); }
  error(...a) { this._emit('error', this._prefix, a); }
  debug(...a) { this._emit('debug', this._prefix, a); }
  success(...a) { this._emit('info', this._prefix, a); }
}
Logger.levels = { success: 0, info: 1, warning: 2, error: 3, debug: 4 };

const SYMBOL_CURRENT = Symbol('koishi.context.current');
const UNSUPPORTED = new Set(['database', 'console', 'model', 'http', 'puppet', 'assets']);

class ContextCore {
  constructor(host, config, label) {
    this._host = host;
    this.config = config || {};
    this._label = label || 'koishi';
    this._commands = new Map();
    this._listeners = new Map();
    this.$commander = {
      // koishi 内部命令注册表的最小投影：官方 help 等插件遍历 _commandList。
      _commandList: [],
      resolve(target, _session) {
        const key = String(target || "").split(/\s+/)[0];
        return this._commandList.find((c) => c.name === key || c.aliases.includes(key)) || null;
      },
      get(name) {
        return this._commandList.find((c) => c.name === String(name)) || null;
      },
    };
    this.before = (event, fn) => this.on(`before/${String(event)}`, fn);
    this.Schema = Schema;
    this.schema = Schema;
    this.logger = (...prefix) => new Logger(prefix.join(':') || this._label, (level, _p, args) => {
      const message = args.map((a) => (typeof a === 'string' ? a : JSON.stringify(a))).join(' ');
      host.log(level, `${prefix.join(':') || this._label} ${message}`);
    });
    this.i18n = {
      define: (locales, dictionary) => {
        const list = Array.isArray(locales) ? locales : [locales];
        for (const locale of list) this._dictionaries[String(locale)] = dictionary || {};
        return this;
      },
      create: (fallback) => ({ text: (key) => String(key), fallback: (locale) => ({ text: (key) => String(key) }) }),
      fallback: (locale) => ({ text: (key) => String(key) }),
      text: (key) => String(key),
    };
    this._dictionaries = {};
    this.koishi = { config: { prefix: ["/"] } };
  }

  command(name, description) {
    const raw = String(name);
    const key = raw.split(/\s+/)[0];
    let command = this._commands.get(key);
    if (!command) {
      command = new Command(key, String(description || raw), this._host, this);
      command.raw_declaration = raw;
      this._commands.set(key, command);
      this.$commander._commandList.push(command);
      this.emit("command-added", command);
    } else if (description) {
      command.description = String(description);
    }
    return command;
  }

  getCommand(name) { return this._commands.get(String(name)); }
  filter(_session) { return true; }
  get commands() { return Object.fromEntries(this._commands); }

  on(event, listener) {
    const key = String(event);
    if (typeof listener !== 'function') return this;
    if (!this._listeners.has(key)) this._listeners.set(key, new Set());
    this._listeners.get(key).add(listener);
    return this;
  }
  addListener(...a) { return this.on(...a); }
  once(event, listener) { return this.on(event, listener); }
  off(event, listener) {
    const set = this._listeners.get(String(event));
    if (set) set.delete(listener);
    return this;
  }
  middleware(fn) { return this.on('message', fn); }
  addMiddleware(fn) { return this.on('message', fn); }
  emit(event, ...args) {
    const set = this._listeners.get(String(event));
    if (!set) return false;
    for (const fn of [...set]) {
      try { fn(...args); } catch (err) { this.logger('bridge').error(err && err.message); }
    }
    return set.size > 0;
  }
  bail(event, ...args) { return this.emit(event, ...args); }
  parallel(event, ...args) { this.emit(event, ...args); return Promise.resolve([]); }
  serial(event, ...args) { this.emit(event, ...args); return Promise.resolve([]); }
}

/** koishi 链式 context 的代理：真实方法优先，未知属性返回新的同型代理。 */
function createContextProxy(core) {
  return new Proxy(core, {
    get(target, prop) {
      if (typeof prop === 'symbol' || prop in target) return target[prop];
      if (UNSUPPORTED.has(String(prop))) {
        throw new Error(`koishi 本地桩未实现 ctx.${String(prop)}：该插件依赖的此服务在桥接下不可用`);
      }
      // koishi 的链式子作用域（ctx.guild()/ctx.platform()/…）：返回同型代理。
      return createContextProxy(new ContextCore(target._host, target.config, `${target._label}.${String(prop)}`));
    },
  });
}

class Command {
  constructor(name, description, host, ctx) {
    this.name = name;
    this.description = description || '';
    this.options = [];
    this.aliases = [];
    this._actions = [];
    this._options = {};
    this.ctx = ctx;           // 官方插件会访问 command.ctx.filter(session)
    this._host = host;
  }
  option(name, description, opts) {
    this.options.push({ name: String(name), description: String(description || ''), config: opts || {} });
    this._options[String(name)] = opts || {};
    return this;
  }
  alias(...names) { this.aliases.push(...names.map(String)); return this; }
  usage(text) { this.usageText = String(text || ''); return this; }
  example(text) { return this; }
  userFields() { return this; }
  channelFields() { return this; }
  before(fn) { return this; }
  action(fn) { this._actions.push(fn); this._action = fn; return this; }
  match(_session) { return true; }   // 桥接下不做二次过滤
  shortcut(name, opts, action) { return this; }   // 官方 help 会注册快捷方式
  _usage() { return this; }
  async run(session) {
    if (!this._actions.length) return undefined;
    const argv = { session, options: session.argv.options || {}, args: session._rest || [], command: this.name };
    let last;
    for (const action of this._actions) {
      last = await action(argv, ...(session._rest || []));
    }
    return last;
  }
}

class Session {
  constructor(payload, host, app) {
    this.host = host;
    this.app = app || null;          // 官方插件会访问 session.app.$commander
    this.content = String(payload.content || '');
    this.username = String(payload.username || 'neko_user');
    this.userId = String(payload.user_id || 'neko_user');
    this.channelId = String(payload.channel_id || 'neko');
    this.isDirect = payload.is_direct !== false;
    this.author = { userId: this.userId, nickname: this.username };
    this.elements = [{ type: 'text', attrs: { content: this.content } }];
    this.event = { member: this.author, message: { content: this.content } };
    this.argv = payload.argv || { name: '', options: {}, args: [] };
    this._rest = Array.isArray(this.argv.args) ? this.argv.args : [];
    this._replies = [];
  }
  async send(text) {
    const body = String(text ?? '');
    this._replies.push(body);
    if (this.host && this.host.send_chat) {
      try { await this.host.send_chat({ text: body }); } catch (_) {}
    }
    return true;
  }
  async sendMessage(text) { return this.send(text); }
  async execute(argv) {
    // 官方语义：执行另一条命令并返回它的输出（本桩按命令名路由到已注册的命令）。
    const name = String((argv && argv.name) || '').split(/\s+/)[0];
    const command = this.app && this.app.getCommand ? this.app.getCommand(name) : null;
    if (!command) throw new Error(`未找到命令：${name}`);
    const sub = new Session(
      {
        content: [name, ...(argv.args || [])].join(' '),
        username: this.username,
        user_id: this.userId,
        channel_id: this.channelId,
        is_direct: this.isDirect,
        argv: { name, options: {}, args: argv.args || [] },
      },
      this.host,
      this.app,
    );
    await command.run(sub);
    return sub._replies.join('\n');
  }
  text(path, params) { return this.resolve(path); }
  resolve(path) {
    // koishi 语义：解析 i18n 模板路径，返回渲染后的字符串
    const key = String(path ?? "");
    const dictionaries = (this.app && this.app.i18n && this.app.i18n._dictionaries) || {};
    for (const dict of Object.values(dictionaries)) {
      if (dict && typeof dict === "object" && key in dict) {
        const value = dict[key];
        return typeof value === "string" ? value : key;
      }
    }
    return key;
  }
  quote() { return null; }
}

class I18nChain {
  text(key) { return String(key); }
}
class I18n {
  define(locales, dictionary) {
    const list = Array.isArray(locales) ? locales : [locales];
    return list;
  }
  create(fallback) { return { text: (key) => String(key) }; }
  find(_key, _target) { return []; }
  fallback(locale) { return { text: (key) => String(key) }; }
  text(key) { return String(key); }
}

function makeContext(host, config) {
  const core = new ContextCore(host, config, 'koishi');
  core.i18n = new I18n();
  return createContextProxy(core);
}

class Context extends ContextCore {
  static get current() { return SYMBOL_CURRENT; }
}

function h(type, attrs, ...children) {
  const node = { type: String(type || ''), attrs: attrs || {}, children: [] };
  for (const child of children.flat(Infinity)) {
    if (child === null || child === undefined || child === false) continue;
    node.children.push(typeof child === 'object' ? child : String(child));
  }
  node.toString = function () {
    const attrs = Object.entries(this.attrs || {})
      .map(([key, value]) => ` ${key}="${h.escape(value)}"`)
      .join('');
    const inner = this.children
      .map((child) => (typeof child === 'string' ? h.escape(child) : child.toString()))
      .join('');
    return `<${this.type}${attrs}>${inner}</${this.type}>`;
  };
  return node;
}
h.parse = (content) => [{
  type: 'text',
  attrs: { content: String(content ?? '') },
  children: [],
}];
h.escape = (value) => String(value).replace(/[&<>"']/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));

module.exports = {
  h,
  Context,
  makeContext,
  Session,
  Command,
  Logger,
  Schema,
  version: '0.0.0-local-shim',
  get database() { throw new Error('koishi 本地桩未实现 database'); },
  get console() { throw new Error('koishi 本地桩未实现 console'); },
};
